        {
          "schema_version": 0,
          "attributes": {
            "set_nested_block": [
              {
                "sensitive_str": "hello world.... but don't tell anyone"
              }
            ]
          },
          "sensitive_attributes": [
            [
              {
                "type": "get_attr",
                "value": "set_nested_block"
              }
            ]
          ]
        }
      ]
